a:54:{s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:1:{i:0;a:1:{s:2:"id";s:2:"75";}}s:6:"upload";a:0:{}s:4:"body";a:3:{s:5:"value";s:4357:"<p><em><strong>Read the blog post: <a href="https://www.previousnext.com.au/blog/hux-alternative-to-hooks" rel="nofollow"> A modern alternative to Hooks</a></strong></em></p>
<p>Hux is a project specifically designed for developers, allowing hook implementations without needing to define a .module file or any kind of proxy class/service features.</p>
<p>There are a few projects out there that try to introduce an event subscriber driven way of working. Hux is an in between solution, allowing the full benefits of dependency injection and class driven logic without going fully in with events. Methods can have the same signature as original hook implementations. Discovery is automatic, only requiring a hook class to be registered as a tagged Drupal service and initial cache clear.</p>
<p>You can also define multiple of the same hook per module!</p>
<p>Requires Drupal 9.4 or later, and PHP 8.0 or later. (Drupal 9.3 users may use a patch in <span class="project-issue-issue-link project-issue-status-info project-issue-status-7"><a href="/project/drupal/issues/2616814" title="Status: Closed (fixed)">#2616814: Delegate all hook invocations to ModuleHandler</a></span>)</p>
<h2>Usage Examples (See <a href="https://git.drupalcode.org/project/hux" rel="nofollow">README.md</a> for more)</h2>
<pre class="codeblock"><code class="language-php">
declare(strict_types=1);

namespace Drupal\my_module;

use Drupal\hux\Attribute\Alter;
use Drupal\hux\Attribute\Hook;
use Drupal\hux\Attribute\ReplaceOriginalHook;

/**
 * Usage examples.
 */
final class MyModuleHooks {

  #[Hook('entity_access')]
  public function myEntityAccess(EntityInterface $entity, string $operation, AccountInterface $account): AccessResultInterface {
    // A barebones implementation.
    return AccessResult::neutral();
  }

  #[Hook('entity_access', priority: 100)]
  public function myEntityAccess2(EntityInterface $entity, string $operation, AccountInterface $account): AccessResultInterface {
    // You can set priority if you have multiple of the same hook!
    return AccessResult::neutral();
  }

  #[Hook('entity_access', moduleName: 'a_different_module', priority: 200)]
  public function myEntityAccess3(EntityInterface $entity, string $operation, AccountInterface $account): AccessResultInterface {
    // You can masquerade as a different module!
    return AccessResult::neutral();
  }

  #[ReplaceOriginalHook(hook: 'entity_access', moduleName: 'media')]
  public function myEntityAccess4(EntityInterface $entity, string $operation, AccountInterface $account): AccessResultInterface {
    // You can override hooks for other modules! E.g \media_entity_access()
    return AccessResult::neutral();
  }


  #[ReplaceOriginalHook(hook: 'entity_access', moduleName: 'media')]
  public function myEntityAccess5(EntityInterface $entity, string $operation, AccountInterface $account, #[OriginalInvoker] callable $originalInvoker): AccessResultInterface {
    // If you override a hook for another module, you can have the original
    // implementation passed to you as a callable!
    $originalResult = $originalInvoker($entity, $operation, $account);
    // Do something...
    return AccessResult::neutral();
  }

  #[Alter('user_format_name')]
  public function myCustomAlter(string &amp;$name, AccountInterface $account): void {
    $name .= ' altered!'; 
  }

  #[
    Hook('entity_insert'),
    Hook('entity_delete'),
  ]
  public function myEntityAccess(EntityInterface $entity): void {
    // Associate with multiple!
    // Also works with Alters and Replacements.
    return AccessResult::neutral();
  }

}

</code></pre><p>
