a:54:{s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:1:{i:0;a:1:{s:2:"id";s:2:"59";}}s:6:"upload";a:0:{}s:4:"body";a:3:{s:5:"value";s:1382:"<p>This module offers to display methods and statics available for an object when using Kint. It was created because the Devel module maintainers decided to remove the Kint plugins responsible for showing object available methods and static class properties in version 3.0 of the module (the <a href="https://gitlab.com/drupalspoons/devel/-/issues/221" rel="nofollow">relevant issue</a>).</p>
<h3>What's the catch?</h3>
<p>The biggest reason to remove these plugins was to prevent out-of-memory errors. So, to make sure you don't run into these when using this module, make sure to add the following snippet to your <code class="language-php">settings.php</code>/<code class="language-php">local.settings.php</code>:</p>
<pre class="codeblock"><code class="language-php">if (class_exists('Kint')) {
  // Change the maximum depth to prevent out-of-memory errors.
  \Kint::$max_depth = 4;
}
</code></pre><p>
In Kint 4 this setting was renamed, so if you're using that version use the following snippet: </p>
<pre class="codeblock"><code class="language-php">if (class_exists('Kint')) {
  // Change the maximum depth to prevent out-of-memory errors.
  \Kint::$depth_limit= 4;
}
</code></pre><h3>Configuration</h3>
<p>Enable this module and select the <em>Kint Extended</em> variables dumper in the Devel settings (<code class="language-php">/admin/config/development/devel</code>).</p>";s:7:"summary";s:196:"This module offers to display methods and statics available for an object when using Kint. It was created because the Devel module maintainers decided to remove the Kint plugins responsible for…";s:6:"format";s:1:"1";}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:17:"devel_kint_extras";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"3164492";s:3:"vid";s:8:"12781961";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s:17:"Devel Kint Extras";s:8:"language";s:2:"en";s:8:"edit_url";s:40:"https://www.drupal.org/node/3164492/edit";s:6:"status";s:1:"1";s:7:"promote";s:1:"0";s:6:"sticky";s:1:"0";s:7:"created";s:10:"1597122838";s:7:"changed";s:10:"1662655388";s:6:"author";a:1:{s:4:"name";s:12:"janchojnacki";}s:14:"book_ancestors";a:0:{}s:7:"comment";s:1:"1";s:8:"comments";a:0:{}s:13:"comment_count";s:1:"0";s: