a:54:{s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:5:"13030";}s:21:"taxonomy_vocabulary_3";a:1:{i:0;a:1:{s:2:"id";s:2:"63";}}s:6:"upload";a:0:{}s:4:"body";a:3:{s:5:"value";s:1282:"<p>This module enables the <a href="https://ckeditor.com/addon/videodetector" rel="nofollow">Video Detector</a> plugin from CKEditor.com in your WYSIWYG. This plugin allows you to insert videos from Youtube, Vimeo or Dailymotion only pasting a URL or embed code. </p>
<h3>Requirements</h3>
<p>CKEditor Module (Core)</p>
<h3>Installation</h3>
<ol>
<li>Download the plugin from <a href="https://ckeditor.com/addon/videodetector" rel="nofollow">https://ckeditor.com/addon/videodetector</a>.</li>
<li>Place the plugin in the root libraries folder (/libraries).</li>
<li>Enable CKEditor Video Detector in the Drupal admin.</li>
<li>Configure your WYSIWYG toolbar to include the buttons.</li>
</ol>
<p>This project only handles the bridge between Video Detector and Drupal. For support to the Video Detector library feel free to  ask at their <a href="http://ckeditor.com/addon/videodetector" rel="nofollow">project page</a>.</p>
<p>If you want to make this video full width in your website add this following css in your theme:</p>
<pre class="codeblock"><code class="language-php">.videodetector {
  position: relative;
  width: 100%;
  height: 0;
  padding-bottom: 60%;
}
.videodetector iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
</code></pre>";s:7:"summary";s:193:"This module enables the Video Detector plugin from CKEditor.com in your WYSIWYG. This plugin allows you to insert videos from Youtube, Vimeo or Dailymotion only pasting a URL or embed code. …";s:6:"format";s:1:"1";}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:22:"ckeditor_videodetector";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:1:{i:0;a:2:{s:4:"file";a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/file/5530633";s:2:"id";s:7:"5530633";s:8:"resource";s:4:"file";}s:3:"alt";s:0:"";}}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a:2:{s:5:"value";s:37:"<p>Module will support Drupal 10.</p>";s:6:"format";s:1:"1";}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"2692701";s:3:"vid";s:8:"12763508";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s:24:"CKEditor: Video Detector";s:8:"language";s:2:"en";s:8:"edit_url";s:40:"https://www.drupal.org/node/2692701/edit";s:6:"status";s:1:"1";s:7:"promote";s:1:"0";s:6:"sticky";s:1:"0";s:7:"created";s:10:"1458720799";s:7:"changed";s:10:"1661281982";s:6:"author";a:1:{s:4:"name";s:8:"darol100";}s:14:"book_ancestors";a:0