a:54:{s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:1:{i:0;a:1:{s:2:"id";s:2:"52";}}s:6:"upload";a:0:{}s:4:"body";a:3:{s:5:"value";s:1130:"<p>Acquia Personalization merges content and customer data into one tool, empowering organizations to deliver the most cohesive and personalized experiences across multiple channels and devices. With the ability to target audiences in real-time, marketers are able to scale their web personalization efforts in order to drive conversions and bottom-line results.</p>
<p>This module provides integration with the Acquia Personalization Service and an enhanced User Experience for Personalization, Testing and Targeting directly on the front-end of your website.</p>
<div class="note-tip">If you are upgrading from the older Acquia Lift module, make sure to uninstall all the lift modules including the Acquia Lift Publisher module, as this new acquia_perz module supersedes and replaces the functionality offered in the Acquia Lift module and its integration with Content Hub. If you were using Content Hub solely as a dependency on Acquia Lift, you can also uninstall all the Acquia Content Hub module. However if you are using Content Hub for content syndication, you must keep the Content Hub modules enabled on your site.</div>";s:7:"summary";s:199:"Acquia Personalization merges content and customer data into one tool, empowering organizations to deliver the most cohesive and personalized experiences across multiple channels and devices. With…";s:6:"format";s:1:"1";}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:11:"acquia_perz";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"3223650";s:3:"vid";s:8:"12757320";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s