a:54:{s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:5:"13030";}s:21:"taxonomy_vocabulary_3";a:3:{i:0;a:1:{s:2:"id";s:2:"57";}i:1;a:1:{s:2:"id";s:2:"58";}i:2;a:1:{s:2:"id";s:2:"59";}}s:4:"body";a:3:{s:5:"value";s:1470:"<p>Paragraph handler allows you to provide "Paragraph Handler" classes that can handle pre-processing and altering the render arrays of Paragraph entities when they are displayed. </p>
<p>This helps to prevent .theme files from getting unruly and allows you to make use of traits and inheritance for your Paragraph display logic.</p>
<p>This module is only useful for developers.</p>
<p>See example below:</p>
<pre class="codeblock"><code class="language-php">
namespace Drupal\mymodule\Plugin\ParagraphHandler;

use Drupal\paragraph_handler\Plugin\ParagraphHandlerBase;
use Drupal\Core\Url;

/**
 * Class Card.
 *
 * @ParagraphHandler(
 *   id = "card",
 *   label = @Translation("Card")
 * )
 */
class Card extends ParagraphHandlerBase {
  /**
   * {@inheritdoc}
   */
  public function preprocess(array &amp;$variables, array $element) {
    if ($this-&gt;isNested()) {
      $variables['nested_class'] = TRUE;
    }

    $variables['new_variable'] = t('Test');
  }

  /**
   * {@inheritdoc}
   */
  public function build(array &amp;$build) {
    $build['link'] = [
      '#type' =&gt; 'link',
      '#title' =&gt; t('Link title'),
      '#text' =&gt; t('Link text'),
      '#url' =&gt; Url::fromUri('&lt;front&gt;'),
    ];
  }
}
</code></pre><p>
Place your paragraph handler under <strong>src\Plugin\ParagraphHandler\</strong> folder inside your module.</p>
<h3>Roadmap</h3>
<ul>
<li>Admin UI to manage paragraph handlers. To enable and disable handlers.</li>
