a:54:{s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:0:{}s:4:"body";a:3:{s:5:"value";s:4641:"<p>By default, the Simplenews module does not enable the user to use the<br />
subscribe / unsubscribe functionality in a decoupled environment, for example, a<br />
React frontend. There are multiple issues with that:</p>
<ul>
<li>The Core Rest API Endpoint does not trigger a confirmation mail if needed</li>
<li>You need the permission 'administer simplenews subscriptions' to use the rest endpoint</li>
<li>Subscribe / unsubscribe url which is sent in the _Mails are always pointing to the D8 installation</li>
</ul>
<p>This module tries to solve these issues.</p>
<p>Here is the open issue in the Simplenews issue queue regarding this<br />
<a href="https://www.drupal.org/project/simplenews/issues/3158939" rel="nofollow">https://www.drupal.org/project/simplenews/issues/3158939</a></p>
<h2>Configuration</h2>
<p><strong>You need to set the base bath to your decoupled environment (this will be used to replace the D8 base URL in the subscribe / unsubscribe URLs)</strong></p>
<p>Add this to your <code class="language-php">settings.php</code>:</p>
<p><code class="language-php">$settings['decoupled_url'] = 'http://localhost:3011';</code></p>
<p><strong>Here are example React Components to show a basic example using the functionality</strong></p>
<p>The newsletter subscribe form component with Formik and axios:</p>
<pre class="codeblock"><code class="language-php">&lt;Formik
  initialValues={{email: ''}}
  onSubmit={values =&gt; {
    axios.post(`${yourBackendUrl}/simplenews-decoupled/subscribe`, {
      "email": values.email,
      "newsletterId": "your_newsletter_id"
    }, {
      withCredentials: true
    })
      .then(result =&gt; console.log(result))
      .catch(error =&gt; console.log(error.response.data.message));
  }}
&gt;
  &lt;Form&gt;
    &lt;Field
      id="email"
      name="email"
      placeholder="E-Mail"
      type="email"
    /&gt;
    &lt;button type="submit"&gt;Submit&lt;/button&gt;
   &lt;/Form&gt;
&lt;/Formik&gt;</code></pre><p>
Route component of the subscribe / unsubscribe confirmation page:</p>
<p><code class="language-php">&lt;Route exact path="/newsletter/confirm/:action/:sid/:newsletter_id/:timestamp/:hash" component={NewsletterConfirm} /&gt;</code></p>
<p>Route component of the combined subscribe / unsubscribe confirmation page<br />
<code class="language-php">&lt;Route exact path="/newsletter/confirm/combined/:sid/:timestamp/:hash" component={NewsletterCombinedConfirm} /&gt;</code></p>
<pre class="codeblock"><code class="language-php">import React, { Component } from 'react';
import PropTypes from 'prop-types';
import axios from 'axios';

class NewsletterConfirm extends Component {
  state = {
    error: false,
    loading: true,
    message: null,
    success: false
  };

  componentDidMount() {
    const { action, sid, newsletter_id, timestamp, hash } = this.props.match.params;

    axios.get(`${yourBackendUrl}/simplenews-decoupled/confirm/${action}/${sid}/${newsletter_id}/${timestamp}/${hash}`)
      .then(response =&gt; {
        this.setState({
          message: response.data.message,
          success: true
        });
      })
      .catch(error =&gt; {
        // Handle error
        this.setState({
          message: error.response.data.message,
          error: true
        });
      })
      .then(() =&gt; {
        this.setState({ loading: false });
      });
  }

  render() {
    return (
      &lt;div&gt;
        {this.state.loading &amp;&amp;
          &lt;Loading /&gt;
        }

        &lt;div className="container"&gt;
          &lt;div className="row"&gt;
            &lt;div className="col-12"&gt;
              {this.props.match.params.action === 'remove' ? (
                &lt;h1&gt;Confirm unsubscription&lt;/h1&gt;
              ) : (
                &lt;h1&gt;Confirm subscription&lt;/h1&gt;
              )}

              {this.state.error &amp;&amp;
              &lt;div className="alert alert-danger" role="alert"&gt;
                {this.state.message}
              &lt;/div&gt;
              }

              {this.state.success &amp;&amp;
              &lt;div className="alert alert-success" role="alert"&gt;
                {this.state.message}
              &lt;/div&gt;
              }

            &lt;/div&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    );
  }
}

NewsletterConfirm.propTypes = {
