a:54:{s:4:"body";a:3:{s:5:"value";s:2240:"<p>Makes the <a href="https://github.com/tabpanelwidget/tabpanelwidget" rel="nofollow">TabPanelWidget</a> library available for various tab and accordion display purposes. Our (government) organization had a need for responsive tabs that would collapse to accordions at narrower widths, and also met accessibility requirements. TabPanelWidget met both needs.</p>
<p>The main <strong>TabPanelWidget</strong> module makes the library available and provides a class for setting options, generating markup, and attaching the library.</p>
<p>The <strong>TabPanelWidget Quick Tabs</strong> module provides a TabRenderer plugin for Quick Tabs.</p>
<p>The <strong>TabPanelWidget Views</strong> module provides a style plugin for Views.</p>
<h2>Installing the library with Composer</h2>
<h3>Option 1: use Composer Merge Plugin</h3>
<p>Include the wikimedia/composer-merge-plugin in your project:</p>
<p><code class="language-php">composer require wikimedia/composer-merge-plugin:^2.0</code></p>
<p>And add the following to the "extra" section of your composer.json file (or, if it already exists, add the tabpanelwidget line to it):</p>
<pre class="codeblock"><code class="language-php">        "merge-plugin": {
            "include": [
                "docroot/modules/contrib/tabpanelwidget/composer.libraries.json"
            ]
        },</code></pre><p>
Composer should then automatically download and install the library when you run <code class="language-php">composer update</code>. You may need to run it twice if this is the first time you've installed the module.</p>
<h3>Option 2: add the custom repository to your composer.json file</h3>
<pre class="codeblock"><code class="language-php">        {
            "type": "package",
            "package": {
                "name": "tabpanelwidget/tabpanelwidget",
                "version": "1.3.2",
                "type": "drupal-library",
                "dist": {
                    "url": "https://github.com/tabpanelwidget/tabpanelwidget/releases/download/1.3.2/tabpanelwidget-1.3.2.zip",
                    "type": "zip"
                }
            }
        },</code></pre><p>
Then use <code class="language-php">composer require tabpanelwidget/tabpanelwidget:^1.3</code>.</p>";s:7:"summary";s:200:"Makes the TabPanelWidget library available for various tab and accordion display purposes. Our (government) organization had a need for responsive tabs that would collapse to accordions at narrower…";s:6:"format";s:1:"1";}s:6:"upload";a:0:{}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:3:{i:0;a:1:{s:2:"id";s:6:"193884";}i:1;a:1:{s:2:"id";s:2:"58";}i:2;a:1:{s:2:"id";s:2:"89";}}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:14:"tabpanelwidget";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:11:"not-covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"3224554";s:3:"vid";s:8:"12550520";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s:14:"TabPanelWidget";s:8:"language";s:2:"en";s:8:"edit_url";s:40:"https://www.drupal.org/node/3224554/edit";s:6:"status";s:1:"1";s:7:"promote";s:1:"0";s:6:"sticky";s:1:"0";s:7:"created";s:10:"1626807485