a:54:{s:4:"body";a:3:{s:5:"value";s:1059:"<p>COOKiES Module Handlers are used to modify the HTML output (especially &lt;script&gt; tags) of a module in the backend so that the execution of Javascript and thus the installation of cookies or the transmission of user data to third parties is suppressed until the User of the website has given his consent. If the user has given their consent, the changes in the front end are reversed so that the Javascript code is loaded and executed.</p>
<p>There are two common methods in Drupal that a module can add Javascript to the HTML of the page. On the one hand the well-known method via libraries, and on the other hand the technique of adding a script tag directly in the header of the HTML page (which is often used by tracking services).</p>
<p>If any module uses one of these methods to integrate critical Javascript code (within the meaning of the GDPR), a COOKiES module handler can be used to effectively switch off this code until the user has given his consent via the COOKiES UI without this individual adjustments must be programmed for this.</p>";s:7:"summary";s:201:"COOKiES Module Handlers are used to modify the HTML output (especially &lt;script&gt; tags) of a module in the backend so that the execution of Javascript and thus the installation of cookies or the…";s:6:"format";s:1:"1";}s:6:"upload";a:0:{}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:4:{i:0;a:1:{s:2:"id";s:5:"13434";}i:1;a:1:{s:2:"id";s:3:"101";}i:2;a:1:{s:2:"id";s:2:"52";}i:3;a:1:{s:2:"id";s:2:"74";}}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:22:"cookies_module_handler";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:11:"not-covered";s:23:"field_project_ecosystem";a:1:{i:0;a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/node/3139023";s:2:"id";s:7:"3139023";s:8:"resource";s:4:"node";}}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replac