a:54:{s:4:"body";a:3:{s:5:"value";s:979:"<p>This module provides links to add an event to a calendar, similar to <a href="/project/addtocal" rel="nofollow">Add to Cal</a> or <a href="/project/addtocalendar" rel="nofollow">Add To Calendar Button</a>. Unlike those modules, this one has no external dependencies or libraries it relies on.</p>
<p>Another key difference is that this module leverages the <a href="/project/date_augmenter" rel="nofollow">Date Augmenter API</a> to provide a plugin that will add these links to another formatter, instead of forcing you to choose a formatter that only adds add to calendar links. So you can use a feature-rich formatter (providing it also supports this API) and add the links to its output.</p>
<p>Because the <a href="https://www.drupal.org/project/smart_date" rel="nofollow">Smart Date</a> module supports the Date Augmenter API as well as recurring dates, using this combination allows your site to provide links that will add the entire recurring series to a calendar.</p>";s:7:"summary";s:195:"This module provides links to add an event to a calendar, similar to Add to Cal or Add To Calendar Button. Unlike those modules, this one has no external dependencies or libraries it relies on…";s:6:"format";s:1:"1";}s:6:"upload";a:0:{}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:3:{i:0;a:1:{s:2:"id";s:2:"57";}i:1;a:1:{s:2:"id";s:2:"61";}i:2;a:1:{s:2:"id";s:2:"52";}}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:16:"addtocal_augment";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:3:{i:0;a:3:{s:3:"uri";s:40:"https://www.drupal.org/api-d7/node/70963";s:2:"id";s:5:"70963";s:8:"resource";s:4:"node";}i:1;a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/node/3208065";s:2:"id";s:7:"3208065";s:8:"resource";s:4:"node";}i:2;a:3:{s:3:"uri";s:42:"ht