a:54:{s:4:"body";a:3:{s:5:"value";s:716:"<p>This module adds a field formatter that expands and collapses to obscure content that is longer than desired. It is similar in principle to <a href="https://www.drupal.org/project/expanding_formatter" rel="nofollow">Expanding Formatter</a>, but operates in a different manner. Rather than trimming based on a number of characters, this module uses a specific height to trim the text. This results in a predictable layout every time.</p>
<h2>How to use this module:</h2>
<p>Enable the module and go to your content type's display settings. You will see on text-based fields (like body) that you now have the ability to choose the "Expandable" option, which will also give you options on the right to configure.</p>";s:7:"summary";s:198:"This module adds a field formatter that expands and collapses to obscure content that is longer than desired. It is similar in principle to Expanding Formatter, but operates in a different manner…";s:6:"format";s:1:"1";}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:5:"13030";}s:21:"taxonomy_vocabulary_3";a:2:{i:0;a:1:{s:2:"id";s:5:"20224";}i:1;a:1:{s:2:"id";s:2:"73";}}s:6:"upload";a:0:{}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:20:"expandable_formatter";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"2984673";s:3:"vid";s:8:"12208544";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s:20:"Expandable Formatter";s:8:"language";s:2:"en";s:8:"edit_url";s:40:"https://www.dru