a:54:{s:4:"body";a:3:{s:5:"value";s:2790:"<p>The module provides a service for storing and retrieving temporary data based on the user session.</p>
<p>This service can be used as like <a href="https://api.drupal.org/api/drupal/core%21modules%21user%21src%21PrivateTempStore.php/class/PrivateTempStore/8.2.x" rel="nofollow">PrivateTempStore</a> to make temporary, non-cache data available across requests. The data is stored in one key/value collection and expires automatically after a given timeframe.</p>
<p>The <strong>SessionBasedTempStore</strong> differs from the <strong>PrivateTempStore</strong> in that it doesn't create Drupal's cookie session, it means that you don't need to be afraid that Varnish will "MISS" the cache for the anonymous user because the cookie session does exist.</p>
<p>However, the issue with the <strong>PrivateTempStore</strong> was brought up here: <a href="https://www.drupal.org/project/drupal/issues/2743931" rel="nofollow">#2743931</a><br />
Unfortunately, it forcibly creates the cookie session for the anonymous user hence it interferes with a static cache like Varnish. </p>
<p>In contrast to <strong>PrivateTempStore</strong>, the <strong>SessionBasedTempStore</strong> creates a separate cookie with the unique ID of the owner storage so that it can subsequently interact with it to retrieve private data.</p>
<p>You may consider this module as a Drupal 8 generation of <a href="https://www.drupal.org/project/session_cache" rel="nofollow">Session Cache API</a></p>
<p>This is an example of how you can use it:</p>
<pre class="codeblock"><code class="language-php">/** @var \Drupal\session_based_temp_store\SessionBasedTempStoreFactory $temp_store_factory */
$temp_store_factory = \Drupal::service('session_based_temp_store');

/** @var \Drupal\session_based_temp_store\SessionBasedTempStore $temp_store */
$temp_store = $temp_store_factory-&gt;get('my_module_name', 4800); 
// As the second argument you can optionally set the exparaion time. If not set, by default it equals 604800 which is 7 days.
// As the third argument you can set the cookie path. The path on the server in which the cookie will be available on. By default, it's set to '/', it means the cookie will be available within the entire domain.
</code></pre><p><br />
Here are the basic methods:</p>
<pre class="codeblock"><code class="language-php">$temp_store-&gt;set('key', 'value');
$temp_store-&gt;get('key');
$temp_store-&gt;delete('key');
</code></pre><p><br />
Additionally this service has following public methods:</p>
<pre class="codeblock"><code class="language-php">// Retrieves an array of all values from the storage for the current collection and owner.
$temp_store-&gt;getAll();
// Deletes all data from the storage for the current collection and owner.
$temp_store-&gt;deleteAll();
</code></pre><p></p>";s:7:"summary";s:202:"The module provides a service for storing and retrieving temporary data based on the user session.
This service can be used as like PrivateTempStore to make temporary, non-cache data available across…";s:6:"format";s:1:"1";}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:1:{i:0;a:1:{s:2:"id";s:2:"59";}}s:6:"upload";a:0:{}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:24:"session_based_temp_store";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:1:{i:0;a:2:{s:4:"file";a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/file/5955946";s:2:"id";s:7:"5955946";s:8:"resource";s:4:"file";}s:3:"alt";s:7:"storage";}}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:11:"not-covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"2946953";s:3:"vid";s:8:"12128848";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s:31:"Session Based Temporary Storage";s:8:"language";s:2:"en";s:8:"edit_url";s:40:"https://www.drupal.org/node/2946953/edit";s:6:"status";s:1:"1";s:7:"promote";s:1:"0";s:6:"sticky";s:1:"0";s:7:"created";s:10:"1519315820";s:7:"changed";s:10:"1605685465";s:6:"author";a:1:{s:4:"name";s:7:"nortmas";}s:14:"book_anc