a:54:{s:4:"body";a:3:{s:5:"value";s:670:"<p>Currently adding pages to a book in the node edit form, and selecting a parent item is a straightforward task and then selecting the position in the tree is simply presented as a weight drop-down.</p>
<p>This always felt like a relatively clumsy device, and often would require the user to frequently re-arrange the book through the drag &amp; drop interface on the book structure form.</p>
<p>Inspired by the <a href="https://www.drupal.org/project/menu_link_weight" rel="nofollow">Menu Link Weight</a> module, this module aims to provide a similar drag &amp; drop tree to the book outline form, allowing a user to simply move the page into position in the tree.</p>";s:7:"summary";s:198:"Currently adding pages to a book in the node edit form, and selecting a parent item is a straightforward task and then selecting the position in the tree is simply presented as a weight drop-down…";s:6:"format";s:1:"1";}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:1:{i:0;a:1:{s:2:"id";s:2:"75";}}s:6:"upload";a:0:{}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:16:"book_link_weight";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:1:{i:0;a:3:{s:3:"uri";s:39:"https://www.drupal.org/api-d7/node/3060";s:2:"id";s:4:"3060";s:8:"resource";s:4:"node";}}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"3177044";s:3:"vid";s:8:"12109976";s:6:"is_new";b:0;s:4:"type";s:14:"projec