a:54:{s:4:"body";a:3:{s:5:"value";s:791:"<p>The module enables to automatically move files to specified folders. Together with the module <a href="https://www.drupal.org/project/private_files_download_permission" rel="nofollow">Private files download permission</a> it is possible to dynamically change the download permissions of files. The files are moved, when a node is saved, which contains references to the files.</p>
<p>You can use the module e.g. for changing file permissions dynamically for several groups of users. When everything is set, then you just choose another taxonomy term in a node and the file(s) will be moved to the appropriate folder.</p>
<p>You can find more information about the module in the <a href="https://git.drupalcode.org/project/move_file/-/blob/8.x-1.x/README.md" rel="nofollow">README</a>.</p>";s:7:"summary";s:68:"The module enables to automatically move files to specified folders.";s:6:"format";s:1:"1";}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:2:{i:0;a:1:{s:2:"id";s:2:"62";}i:1;a:1:{s:2:"id";s:2:"67";}}s:6:"upload";a:0:{}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:9:"move_file";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:1:{i:0;a:2:{s:4:"file";a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/file/6308289";s:2:"id";s:7:"6308289";s:8:"resource";s:4:"file";}s:3:"alt";s:18:"Move File Settings";}}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:1:{i:0;a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/node/1278170";s:2:"id";s:7:"1278170";s:8:"resource";s:4:"node";}}s:29:"field_next_major_version_info";a:0:{}s:17:"field_replaced_by";a:0:{}s:28:"field_issue_summary_template";a:0:{}s:3:"nid";s:7:"3115871";s:3:"vid";s:8:"11863460";s:6:"is_new";b:0;s:4:"type";s:14:"project_module";s:5:"title";s:9:"Move File";s: