a:54:{s:4:"body";a:3:{s:5:"value";s:662:"<p>The module lets you trigger notifications depending on the current status of your migrations in production. It checks if migrations are not idle and compares them to their last state to determine whether they might be stuck or not.</p>
<p>Notifications can be triggered via cron or instantly. Slack and email are currently supported.</p>
<p><strong>Note</strong>: if cron runs too frequently (or faster than a migration can be running) or if we check too frequently this could throw false negatives. Migrations do NOT have a stuck status, so the logic is that if, in between checks, the status of the same migration is not idle then we consider it stuck. </p>";s:7:"summary";s:198:"The module lets you trigger notifications depending on the current status of your migrations in production. It checks if migrations are not idle and compares them to their last state to determine…";s:6:"format";s:1:"1";}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"13028";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:4:"9988";}s:21:"taxonomy_vocabulary_3";a:3:{i:0;a:1:{s:2:"id";s:2:"57";}i:1;a:1:{s:2:"id";s:2:"64";}i:2;a:1:{s:2:"id";s:2:"75";}}s:6:"upload";a:0:{}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:16:"migration_notify";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:1:{i:0;a:2:{s:4:"file";a:3:{s:3:"uri";s:42:"https://www.drupal.org/api-d7/file/6288479";s:2:"id";s:7:"6288479";s:8:"resource";s:4:"file";}s:3:"alt";s:25:"Migration Notify settings";}}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:0:{}s:29:"field_next_major_version_info";a