a:54:{s:4:"body";a:3:{s:5:"value";s:1189:"<p>This module implements integration between Webform and the AddressFinder  service (<a href="https://addressfinder.com.au/" rel="nofollow">https://addressfinder.com.au/</a>), providing autocompletion and validation for addresses in Australia and New Zealand.</p>
<p>To use the module, install (composer require drupal/webform_location_addressFinder) and enable it as you would any other drupal module, then visit /admin/structure/webform/config/elements, tick the checkbox next to "Location (AddressFinder)" in the Element Types table and save the updated configuration. You can then add a "Location (AddressFinder)" element in the configuration of a form. The AddressFinder API key is entered in the element configuration, on the General tab, at the bottom of the 'Location (AddressFinder) settings' section of the form.</p>
<p>The module was based on the Algolia Places plugin, and developed by Ladoo as part of the build of a new site for Victoria's Road Safety Camera Commissioner (<a href="https://cameracommissioner.vic.gov.au" rel="nofollow">https://cameracommissioner.vic.gov.au</a>). The module has been released to the public domain with the permission of the Commissioner.</p>";s:7:"summary";s:200:"This module implements integration between Webform and the AddressFinder  service (https://addressfinder.com.au/), providing autocompletion and validation for addresses in Australia and New Zealand…";s:6:"format";s:1:"1";}s:22:"taxonomy_vocabulary_44";a:1:{s:2:"id";s:5:"19370";}s:22:"taxonomy_vocabulary_46";a:1:{s:2:"id";s:5:"13030";}s:21:"taxonomy_vocabulary_3";a:3:{i:0;a:1:{s:2:"id";s:2:"60";}i:1;a:1:{s:2:"id";s:2:"65";}i:2;a:1:{s:2:"id";s:3:"119";}}s:6:"upload";a:0:{}s:18:"field_project_type";s:4:"full";s:26:"field_project_machine_name";s:30:"webform_location_addressfinder";s:29:"field_project_has_issue_queue";b:1;s:24:"field_project_components";a:4:{i:0;s:4:"Code";i:1;s:13:"Documentation";i:2;s:13:"Miscellaneous";i:3;s:14:"User interface";}s:31:"field_project_default_component";N;s:30:"field_project_issue_guidelines";a:0:{}s:26:"field_project_has_releases";b:1;s:28:"field_release_version_format";N;s:22:"field_project_homepage";a:0:{}s:23:"field_project_changelog";a:0:{}s:18:"field_project_demo";a:0:{}s:27:"field_project_documentation";a:0:{}s:25:"field_project_screenshots";a:0:{}s:21:"field_project_license";a:3:{s:3:"url";s:53:"http://www.gnu.org/licenses/old-licenses/gpl-2.0.html";s:10:"attributes";a:0:{}s:11:"display_url";N;}s:20:"field_project_images";a:0:{}s:32:"field_project_issue_version_opts";a:2:{i:0;s:6:"static";i:1;s:7:"dynamic";}s:32:"field_security_advisory_coverage";s:7:"covered";s:23:"field_project_ecosystem";a:1:{i:0;a:3:{s:3:"uri";s:39:"https://www.drupal.org/api-d7/node/7404";s:2:"id";s:4:"7404";s:8:"resource";s:4:"node";}}s:29:"field_next_major_version_info";a:0:{}s:1